            public init(deviceID: String, name: String) {
                self.deviceID = deviceID
                self.name = name
            }

            enum CodingKeys: String, CodingKey {
                case deviceID = "device_id"
                case name
            }
        }

        public struct Response: Codable, Hashable, Sendable {
            public var device: WsModel.Device

            public init(device: WsModel.Device) {
                self.device = device
            }

            enum CodingKeys: String, CodingKey {
                case device
            }
        }
    }
}

extension Ws.Device {
    /// Unpair a device (its user, a super admin, or the device itself). Final: its live sessions close at once and its
    /// key only ever gets pairing-only connections again.
    public enum Revoke: WsRequest {
        public static let command = WsCommand.deviceRevoke

        public struct Payload: Codable, Hashable, Sendable {
            /// The device id: the SHA-256 of its certificate's SubjectPublicKeyInfo (64 lowercase hex digits).
            public var deviceID: String

            public init(deviceID: String) {
                self.deviceID = deviceID
            }

            enum CodingKeys: String, CodingKey {
                case deviceID = "device_id"
            }
        }

        public struct Response: Codable, Hashable, Sendable {
            public var device: WsModel.Device

            public init(device: WsModel.Device) {
                self.device = device
            }

            enum CodingKeys: String, CodingKey {
                case device
            }
        }
    }
}

extension Ws.Device.Server {
    /// The server key's SPKI hash (the pin). A next key is never announced: a new server key means pairing again.
    public enum Identity: WsRequest {
        public static let command = WsCommand.deviceServerIdentity
        /// The daemon reads nothing; the payload is sent as null.
        public typealias Payload = WsNoPayload

        public struct Response: Codable, Hashable, Sendable {
            /// 64 lowercase hex digits (a SHA-256 value).
            public var spkiSha256: String

            public init(spkiSha256: String) {
                self.spkiSha256 = spkiSha256
            }

            enum CodingKeys: String, CodingKey {
                case spkiSha256 = "spki_sha256"
            }
        }
    }
}
